import React, { useState, useEffect } from 'react';
import { getFranchises } from '../services/api'; // Assuming you have `getFranchises` function

const ExamData = () => {
  const [filterFranchiseId, setFilterFranchiseId] = useState(''); // State to store the selected filter
  const [franchises, setFranchises] = useState([]); // Store the list of franchises
  const [examDataList, setExamDataList] = useState([]); // Store the list of exam data
  const [formData, setFormData] = useState({
    examName: '',
    date: '',
    studentsAttended: '',
    franchiseId: '',
  }); // Store form data
  const [editIndex, setEditIndex] = useState(null); // Track the index being edited

  // Fetch franchises and their exam data on component mount
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data); // Assuming the response contains an array of franchises
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []); // Run once when the component mounts

  // Filter exam data based on selected franchise
  const filteredExamData = filterFranchiseId
    ? examDataList.filter((exam) => exam.franchiseId === filterFranchiseId)
    : examDataList;

  // Get the exam data for the selected franchise
  const getFranchiseExams = (franchiseId) => {
    const franchise = franchises.find((f) => f._id === franchiseId);
    return franchise ? franchise.examData : [];
  };

  // Get franchise name based on the ID
  const getFranchiseName = (id) => {
    const franchise = franchises.find((f) => f._id === id);
    return franchise ? franchise.name : 'Unknown Franchise';
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Handle the creation and updating of exam data
  const handleSubmit = (e) => {
    e.preventDefault();

    if (editIndex !== null) {
      // Edit existing exam data
      const updatedExamData = { ...formData };
      setExamDataList((prevData) => {
        const updatedData = [...prevData];
        updatedData[editIndex] = updatedExamData;
        return updatedData;
      });
      setEditIndex(null);
      alert('Exam data updated successfully!');
    } else {
      // Create new exam data
      setExamDataList((prevData) => [...prevData, formData]);
      alert('Exam data created successfully!');
    }

    // Reset the form after submission
    setFormData({
      examName: '',
      date: '',
      studentsAttended: '',
      franchiseId: '',
    });
  };

  // Handle the editing of exam data
  const handleEdit = (index) => {
    const examToEdit = examDataList[index];
    setFormData({
      examName: examToEdit.examName,
      date: examToEdit.date,
      studentsAttended: examToEdit.studentsAttended,
      franchiseId: examToEdit.franchiseId,
    });
    setEditIndex(index);
  };

  // Handle deleting exam data
  const handleDelete = (index) => {
    if (window.confirm('Are you sure you want to delete this exam data?')) {
      setExamDataList((prevData) => prevData.filter((_, i) => i !== index));
      alert('Exam data deleted successfully!');
    }
  };

  return (
    <div>
      <h1>Manage Exam Data</h1>

      {/* Franchise filter dropdown */}
      <div>
        <label htmlFor="filterFranchiseId">Filter by Franchise:</label>
        <select
          id="filterFranchiseId"
          name="filterFranchiseId"
          value={filterFranchiseId}
          onChange={(e) => {
            const selectedFranchiseId = e.target.value;
            setFilterFranchiseId(selectedFranchiseId);

            // Fetch exam data for the selected franchise
            if (selectedFranchiseId) {
              const exams = getFranchiseExams(selectedFranchiseId);
              setExamDataList(exams);
            } else {
              setExamDataList([]);
            }
          }}
        >
          <option value="">All</option>
          {franchises.map((franchise) => (
            <option key={franchise._id} value={franchise._id}>
              {franchise.name}
            </option>
          ))}
        </select>
      </div>

      {/* Exam data creation / editing form */}
      <h2>{editIndex !== null ? 'Edit' : 'Create'} Exam Data</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="franchiseId">Franchise:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={formData.franchiseId}
            onChange={handleChange}
            required
          >
            <option value="">Select Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label htmlFor="examName">Exam Name:</label>
          <input
            id="examName"
            name="examName"
            value={formData.examName}
            onChange={handleChange}
            placeholder="Enter Exam Name"
            required
          />
        </div>
        <div>
          <label htmlFor="date">Date:</label>
          <input
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="studentsAttended">Students Attended:</label>
          <input
            id="studentsAttended"
            name="studentsAttended"
            type="number"
            value={formData.studentsAttended}
            onChange={handleChange}
            placeholder="Number of Students"
            required
          />
        </div>
        <button type="submit">{editIndex !== null ? 'Update' : 'Create'} Exam Data</button>
      </form>

      <h2>Exam Data</h2>
      {filteredExamData.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Franchise Name</th>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredExamData.map((exam, index) => (
              <tr key={index}>
                <td>{getFranchiseName(exam.franchiseId)}</td>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
                <td>
                  <button onClick={() => handleEdit(index)}>Edit</button>
                  <button onClick={() => handleDelete(index)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available for the selected franchise.</p>
      )}
    </div>
  );
};

export default ExamData;
